# Build 22x22 solution from component coordinates (0-based)
H=W=22
grid=[[0]*W for _ in range(H)]
objects={
 '4': {'color':[(r,c) for r in range(10,13) for c in range(8,11)], 'marks':[(9,9),(11,11),(12,11),(13,9)], 'shift':(0,0)},
 '1': {'color':[(9,2),(9,3),(10,3),(11,3),(12,2),(12,3)], 'marks':[(9,1),(12,1)], 'shift':(3,13)},
 '3': {'color':[(16,9),(16,10),(17,10),(18,6),(18,10)]+[(19,c) for c in range(6,11)], 'marks':[(16,8),(16,11),(17,6),(19,11)], 'shift':(-4,3)},
 '6': {'color':[(2,c) for c in range(4,9)]+[(3,4),(3,8),(4,8),(5,8),(6,7),(6,8)], 'marks':[(2,9),(4,4),(4,9),(6,6)], 'shift':(5,5)},
 '5': {'color':[(16,c) for c in range(16,19)]+[(17,18)]+[(18,c) for c in range(16,19)], 'marks':[(16,15),(18,15)], 'shift':(-9,-1)},
}
places=[]
for name,obj in objects.items():
 dr,dc=obj['shift']
 for kind,coords in [('color',obj['color']),('mark',obj['marks'])]:
  for r,c in coords:
   rr,cc=r+dr,c+dc
   places.append((rr,cc,name,kind))
   if not (0<=rr<H and 0<=cc<W): print('out',name,kind,rr,cc)
# collisions at colors or marker positions
from collections import defaultdict
at=defaultdict(list)
for r,c,n,k in places: at[(r,c)].append((n,k))
[(p,x) for p,x in at.items() if len(x)>1][:20], len([1 for x in at.values() if len(x)>1])
